import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { adminApi } from '../api/admin';
import { useAuth } from '../context/AuthContext';
import { useShop } from '../context/ShopContext';
import {
  Package,
  Layers,
  GraduationCap,
  Sparkles,
  Plus,
  Edit,
  Trash2,
  RefreshCw,
  Loader2,
  AlertCircle,
  Clock,
  Eye,
  CheckCircle2,
} from 'lucide-react';

export const CreatorCatalog: React.FC = () => {
  const { user } = useAuth();
  const { formatPrice, deleteItem } = useShop();

  const [catalogGroups, setCatalogGroups] = useState<Array<{ type: string; items: any[]; total: number }>>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedType, setSelectedType] = useState<string>('all');
  const [deletingId, setDeletingId] = useState<string | null>(null);

  const fetchCreatorItems = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await adminApi.getCreatorCatalog(1, 100);
      setCatalogGroups(res.catalog);
    } catch (err: any) {
      setError(err?.error || err?.message || 'Could not load creator catalog.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCreatorItems();
  }, []);

  const handleDelete = async (type: string, id: string) => {
    if (!window.confirm('Are you sure you want to delete this catalog release? This action is destructive.')) {
      return;
    }
    setDeletingId(id);
    try {
      await deleteItem(type as any, id);
      await fetchCreatorItems();
    } catch (err: any) {
      alert(err?.error || err?.message || 'Failed to delete release.');
    } finally {
      setDeletingId(null);
    }
  };

  const allItems = catalogGroups.flatMap(group =>
    (group.items || []).map(item => ({ ...item, catalogType: group.type || item.type }))
  );

  const filteredItems = selectedType === 'all'
    ? allItems
    : allItems.filter(i => (i.catalogType || i.type) === selectedType);

  const getStatusBadge = (status: string, isActive?: boolean) => {
    const s = (status || (isActive ? 'published' : 'draft')).toLowerCase();
    switch (s) {
      case 'published':
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20">
            Published
          </span>
        );
      case 'review':
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-amber-500/10 text-amber-600 dark:text-amber-400 border border-amber-500/20">
            Review
          </span>
        );
      case 'out_of_stock':
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20">
            Out of Stock
          </span>
        );
      case 'archived':
      case 'discontinued':
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-slate-200 dark:bg-slate-800 text-slate-500 border border-slate-300 dark:border-slate-700">
            {s}
          </span>
        );
      default:
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
            Draft
          </span>
        );
    }
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8 pb-6 border-b border-slate-200 dark:border-slate-800">
        <div>
          <div className="flex items-center gap-2">
            <span className="text-[11px] font-mono uppercase tracking-wider text-emerald-600 dark:text-emerald-400 font-bold">
              STUDIO WORKSPACE
            </span>
            <span className="px-2 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20">
              Owned Releases (All Statuses)
            </span>
          </div>
          <h1 className="font-display text-2xl sm:text-3xl font-bold text-slate-900 dark:text-white mt-1">
            Creator Catalog Management
          </h1>
          <p className="text-xs sm:text-sm text-slate-500 dark:text-slate-400 mt-1">
            Manage your drafts, active releases, and archived systems with source code access.
          </p>
        </div>

        <div className="flex items-center gap-2.5">
          <Link
            to="/admin/product/new"
            className="px-3.5 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold inline-flex items-center gap-1.5 transition-colors"
          >
            <Plus size={13} />
            <span>New Product</span>
          </Link>
          <Link
            to="/admin/course/new"
            className="px-3.5 py-2 rounded-xl bg-amber-600 hover:bg-amber-500 text-white text-xs font-semibold inline-flex items-center gap-1.5 transition-colors"
          >
            <Plus size={13} />
            <span>New Course</span>
          </Link>
          <Link
            to="/admin/bundle/new"
            className="px-3.5 py-2 rounded-xl bg-purple-600 hover:bg-purple-500 text-white text-xs font-semibold inline-flex items-center gap-1.5 transition-colors"
          >
            <Plus size={13} />
            <span>New Bundle</span>
          </Link>
          <button
            type="button"
            onClick={fetchCreatorItems}
            disabled={loading}
            className="p-2 rounded-xl border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-900 text-slate-500 transition-colors"
          >
            <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
          </button>
        </div>
      </div>

      {/* Filter Tabs */}
      <div className="flex items-center gap-2 mb-6 overflow-x-auto pb-2">
        {['all', 'product', 'course', 'bundle', 'subscription'].map(tab => (
          <button
            key={tab}
            type="button"
            onClick={() => setSelectedType(tab)}
            className={`px-3.5 py-1.5 rounded-lg text-xs font-semibold capitalize transition-colors ${
              selectedType === tab
                ? 'bg-slate-900 dark:bg-white text-white dark:text-slate-950'
                : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-900'
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      {loading ? (
        <div className="flex flex-col items-center justify-center py-20 text-slate-400">
          <Loader2 size={32} className="animate-spin text-emerald-500 mb-3" />
          <span className="text-xs font-mono">Loading creator workspace...</span>
        </div>
      ) : error ? (
        <div className="p-8 rounded-2xl bg-rose-500/10 border border-rose-500/20 text-center max-w-md mx-auto">
          <AlertCircle size={28} className="text-rose-500 mx-auto mb-3" />
          <h2 className="font-display text-base font-bold text-slate-900 dark:text-white mb-1">
            Could Not Load Catalog
          </h2>
          <p className="text-xs text-slate-500 dark:text-slate-400 mb-4">{error}</p>
          <button
            type="button"
            onClick={fetchCreatorItems}
            className="px-4 py-2 bg-emerald-600 text-white rounded-lg text-xs font-semibold"
          >
            Retry
          </button>
        </div>
      ) : filteredItems.length === 0 ? (
        <div className="p-12 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 text-center max-w-md mx-auto">
          <Package size={30} className="text-slate-400 mx-auto mb-3" />
          <h2 className="font-display text-lg font-bold text-slate-900 dark:text-white mb-1">
            No Releases Found
          </h2>
          <p className="text-xs text-slate-500 dark:text-slate-400 mb-6">
            You do not have any published or draft items in this category yet.
          </p>
          <Link
            to="/admin/product/new"
            className="inline-flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-xl text-xs font-semibold"
          >
            <Plus size={13} />
            <span>Create Release</span>
          </Link>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredItems.map(item => {
            const id = item._id || item.id;
            const itemType = item.catalogType || item.type || 'product';
            const editUrl =
              itemType === 'course'
                ? `/admin/course/edit/${id}`
                : itemType === 'bundle'
                ? `/admin/bundle/edit/${id}`
                : `/admin/product/edit/${id}`;

            return (
              <div
                key={id}
                className="p-5 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between"
              >
                <div>
                  <div className="flex items-center justify-between gap-2 mb-3">
                    <span className="text-[10px] font-mono uppercase px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300">
                      {itemType}
                    </span>
                    {getStatusBadge(item.status, item.isActive)}
                  </div>

                  <h3 className="font-display text-base font-bold text-slate-900 dark:text-white line-clamp-1 mb-1">
                    {item.name || item.title || 'Untitled'}
                  </h3>

                  <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-2 mb-3">
                    {item.description || 'No description provided.'}
                  </p>

                  <div className="text-xs font-mono font-bold text-slate-900 dark:text-white mb-2">
                    {formatPrice(item.price, item.currency)}
                  </div>
                </div>

                <div className="pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between gap-2">
                  <div className="flex items-center gap-2">
                    <Link
                      to={editUrl}
                      className="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-800 text-xs font-semibold text-slate-700 dark:text-slate-300 inline-flex items-center gap-1.5 transition-colors"
                    >
                      <Edit size={12} />
                      <span>Edit</span>
                    </Link>
                    <Link
                      to={`/item/${item.slug || id}`}
                      className="p-1.5 rounded-lg text-slate-400 hover:text-slate-900 dark:hover:text-white transition-colors"
                      title="View public storefront page"
                    >
                      <Eye size={14} />
                    </Link>
                  </div>

                  <button
                    type="button"
                    disabled={deletingId === id}
                    onClick={() => handleDelete(itemType, id)}
                    className="p-1.5 rounded-lg text-slate-400 hover:text-rose-500 disabled:opacity-50 transition-colors"
                    title="Delete release"
                  >
                    <Trash2 size={14} />
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default CreatorCatalog;
